_PAINT_ICON_CACHE = {}


def original_icon(key):
    if key not in PAINT_ICON_DATA:return None
    if key not in _PAINT_ICON_CACHE:
        icon=QIcon()
        for encoded in PAINT_ICON_DATA[key]:
            pixmap=QPixmap()
            if not pixmap.loadFromData(base64.b64decode(encoded),'PNG'):
                raise ValueError(f'Invalid embedded Paint icon: {key}')
            icon.addPixmap(pixmap)
        _PAINT_ICON_CACHE[key]=icon
    return QIcon(_PAINT_ICON_CACHE[key])


def tool_icon(tool):
    return original_icon(tool) or QIcon()


def clipboard_image(mime=None):
    """Finder copies file URLs; browsers and screenshot tools usually copy pixels."""
    mime=mime or QApplication.clipboard().mimeData()
    if mime is None:return QImage()
    for url in mime.urls():
        if not url.isLocalFile():continue
        reader=QImageReader(url.toLocalFile());reader.setAutoTransform(True)
        size=reader.size()
        if size.isValid() and size.width()*size.height()>MAX_PIXELS:continue
        image=reader.read()
        if not image.isNull() and image.width()*image.height()<=MAX_PIXELS:return image
    if mime.hasImage():
        image=mime.imageData()
        if isinstance(image,QPixmap):image=image.toImage()
        if isinstance(image,QImage) and image.width()*image.height()<=MAX_PIXELS:return image
    return QImage()


TEXT_FRAME = 6  # screen pixels around the text area used for moving / resizing


class TextEditor(QPlainTextEdit):
    def __init__(self,box):
        super().__init__(box)
        self.box=box
        self.setFrameShape(QFrame.Shape.NoFrame)
        self.setHorizontalScrollBarPolicy(Qt.ScrollBarPolicy.ScrollBarAlwaysOff)
        self.setVerticalScrollBarPolicy(Qt.ScrollBarPolicy.ScrollBarAlwaysOff)
        self.setLineWrapMode(QPlainTextEdit.LineWrapMode.WidgetWidth)
        self.setWordWrapMode(QTextOption.WrapMode.WrapAtWordBoundaryOrAnywhere)
        self.document().setDocumentMargin(0)
        self.viewport().setAutoFillBackground(False)
        self.viewport().setCursor(Qt.CursorShape.IBeamCursor)

    def keyPressEvent(self,event):
        canvas=self.box.canvas
        if event.key()==Qt.Key.Key_Escape:
            canvas.cancel_text();return
        if event.key() in (Qt.Key.Key_Return,Qt.Key.Key_Enter) and event.modifiers() & (Qt.KeyboardModifier.ControlModifier|Qt.KeyboardModifier.MetaModifier):
            canvas.commit_text();return
        super().keyPressEvent(event)


class TextBox(QWidget):
    # Dashed frame with 8 sizing handles, like MS Paint. Handles resize, the rest of the border moves.
    CURSORS={'l':Qt.CursorShape.SizeHorCursor,'r':Qt.CursorShape.SizeHorCursor,
             't':Qt.CursorShape.SizeVerCursor,'b':Qt.CursorShape.SizeVerCursor,
             'tl':Qt.CursorShape.SizeFDiagCursor,'br':Qt.CursorShape.SizeFDiagCursor,
             'tr':Qt.CursorShape.SizeBDiagCursor,'bl':Qt.CursorShape.SizeBDiagCursor,
             'move':Qt.CursorShape.SizeAllCursor}

    def __init__(self,canvas):
        super().__init__(canvas)
        self.canvas=canvas
        self.editor=TextEditor(self)
        self.setFocusProxy(self.editor)
        self.setMouseTracking(True)
        self.drag=None
        self.setToolTip(tr('Drag the border to move, drag a handle to resize. Command/Ctrl+Enter applies; Escape cancels.'))

    def toPlainText(self):
        return self.editor.toPlainText()

    def zone(self,pos):
        m=TEXT_FRAME;w,h=self.width(),self.height();x,y=pos.x(),pos.y()
        if m<=x<w-m and m<=y<h-m:return None
        c=m+5
        left,right,top,bottom=x<c,x>=w-c,y<c,y>=h-c
        if (left or right) and (top or bottom):
            return ('t' if top else 'b')+('l' if left else 'r')
        if top or bottom:
            if abs(x-w/2)<=max(8,(w-2*m)/4):return 't' if top else 'b'
            return 'move'
        if abs(y-h/2)<=max(8,(h-2*m)/4):return 'l' if left else 'r'
        return 'move'

    def mousePressEvent(self,event):
        z=self.zone(event.position())
        if event.button()==Qt.MouseButton.LeftButton and z:
            self.drag=(z,QPointF(event.globalPosition()),QRect(self.canvas.text_origin,self.canvas.text_box_size))
            event.accept()
        else:
            super().mousePressEvent(event)

    def mouseMoveEvent(self,event):
        if self.drag is None:
            self.setCursor(self.CURSORS.get(self.zone(event.position()),Qt.CursorShape.ArrowCursor));return
        zone,origin,start=self.drag;c=self.canvas
        d=(event.globalPosition()-origin)/c.zoom;dx,dy=round(d.x()),round(d.y())
        W,H=c.image.width(),c.image.height()
        L,T=start.left(),start.top();R,B=L+start.width(),T+start.height()
        if zone=='move':
            L=max(0,min(W-start.width(),L+dx));T=max(0,min(H-start.height(),T+dy))
            R,B=L+start.width(),T+start.height()
        else:
            minw=max(10,c.text_base_font().pixelSize())
            if 'l' in zone:L=max(0,min(R-minw,L+dx))
            if 'r' in zone:R=min(W,max(L+minw,R+dx))
            minh=min(H,c.text_content_height(R-L))
            if 't' in zone:T=max(0,min(B-minh,T+dy))
            if 'b' in zone:B=min(H,max(T+minh,B+dy))
        c.text_origin=QPoint(L,T);c.text_box_size=QSize(max(1,R-L),max(1,B-T))
        c.update_text_box()

    def mouseReleaseEvent(self,event):
        if self.drag is not None:
            self.drag=None;self.editor.setFocus();event.accept()
        else:
            super().mouseReleaseEvent(event)

    def leaveEvent(self,event):
        if self.drag is None:self.unsetCursor()
        super().leaveEvent(event)

    def paintEvent(self,event):
        p=QPainter(self);m=TEXT_FRAME
        r=QRectF(m-0.5,m-0.5,self.width()-2*m+1,self.height()-2*m+1)
        p.setPen(QPen(QColor('#3c7fb1'),1,Qt.PenStyle.DashLine));p.setBrush(Qt.BrushStyle.NoBrush)
        p.drawRect(r)
        p.setPen(QPen(QColor('#5a6878'),1));p.setBrush(QColor('white'))
        cx,cy=r.center().x(),r.center().y()
        for x in (r.left(),cx,r.right()):
            for y in (r.top(),cy,r.bottom()):
                if x==cx and y==cy:continue
                p.drawRect(QRectF(x-2.5,y-2.5,5,5))
        p.end()


class Canvas(QWidget):
    changed = Signal()
    position = Signal(str)
    picked = Signal(QColor, bool)
    zoomed = Signal(int)
    selection_changed = Signal()
    resize_preview_changed = Signal(object)

    def __init__(self):
        super().__init__()
        self.image = blank(354, 408)
        self.undo_stack, self.redo_stack = [], []
        self.history_budget = 128 * 1024 * 1024
        self.tool, self.brush_style = 'brush', 'Round'
        self.primary, self.secondary = QColor('black'), QColor('white')
        self.stroke_width = 3
        self.outline, self.fill = True, False
        self.outline_style=Qt.PenStyle.SolidLine;self.bucket_fill=True
        self.antialias = True
        self.hardness = 100
        self.eraser_shape = 'round'
        self.text_font = QFont('Arial', 18)
        self.text_entry=None
        self.text_opaque=False
        self.text_origin=QPoint()
        self.text_box_size=QSize()
        self.zoom, self.grid = 1.0, False
        self.selection = QRect()
        self.floating = None
        self.selection_mode='rect'           # 'rect' or 'free'
        self.transparent_selection=False
        self.lasso=None
        self._cursor_cache={}
        self.dragging = False
        self.start = self.last = self.end = QPoint()
        self.before = None
        self.right_button = False
        self.moving = False
        self.resize_drag = False
        self.setMouseTracking(True)
        self.setAcceptDrops(True)
        self.setFocusPolicy(Qt.FocusPolicy.StrongFocus)
        self.sync_size()

    @property
    def selection(self):return self._selection

    @selection.setter
    def selection(self,value):
        self._selection=QRect(value)
        self.selection_shape=None   # optional QPainterPath, relative to selection.topLeft()
        self.selection_changed.emit()

    @property
    def primary(self):return self._primary

    @primary.setter
    def primary(self,value):
        self._primary=QColor(value)
        if getattr(self,'text_entry',None) is not None:
            self.text_color=QColor(value);self.update_text_box()

    @property
    def secondary(self):return self._secondary

    @secondary.setter
    def secondary(self,value):
        self._secondary=QColor(value)
        if getattr(self,'text_entry',None) is not None:self.update_text_box()

    @property
    def text_opaque(self):return getattr(self,'_text_opaque',False)

    @text_opaque.setter
    def text_opaque(self,value):
        self._text_opaque=bool(value)
        if getattr(self,'text_entry',None) is not None:self.update_text_box()

    def sync_size(self):
        self.setFixedSize(round(self.image.width() * self.zoom) + 10,
                          round(self.image.height() * self.zoom) + 10)
        self.update()

    def snapshot(self):
        self.undo_stack.append(self.composite())
        total = sum(im.sizeInBytes() for im in self.undo_stack)
        while len(self.undo_stack) > 1 and total > self.history_budget:
            total -= self.undo_stack.pop(0).sizeInBytes()
        self.redo_stack.clear()

    def modified(self):
        self.changed.emit()
        self.update()

    def set_image(self, image, remember=True):
        self.commit_selection()
        if remember:
            self.snapshot()
        self.image = image.convertToFormat(QImage.Format.Format_ARGB32)
        self.selection = QRect()
        self.sync_size()
        self.modified()

    def undo(self):
        self.dragging = False
        self.moving = False
        self.commit_selection()
        if self.undo_stack:
            self.redo_stack.append(self.image.copy())
            self.image = self.undo_stack.pop()
            self.selection = QRect()
            self.sync_size()
            self.modified()

    def redo(self):
        self.dragging = False
        self.moving = False
        self.commit_selection()
        if self.redo_stack:
            self.undo_stack.append(self.image.copy())
            self.image = self.redo_stack.pop()
            self.selection = QRect()
            self.sync_size()
            self.modified()

    def set_zoom(self, percentage):
        self.zoom = percentage / 100
        self.update_text_box()
        self.sync_size()
        self.zoomed.emit(percentage)

    def document_point(self, event):
        return QPoint(int(event.position().x() / self.zoom),
                      int(event.position().y() / self.zoom))

    @classmethod
    def checker_pixmap(cls):
        if not hasattr(cls, '_checker'):
            pix = QPixmap(16, 16)
            p = QPainter(pix)
            p.fillRect(0, 0, 8, 8, QColor('#ffffff'))
            p.fillRect(8, 0, 8, 8, QColor('#e2e4e8'))
            p.fillRect(0, 8, 8, 8, QColor('#e2e4e8'))
            p.fillRect(8, 8, 8, 8, QColor('#ffffff'))
            p.end()
            cls._checker = pix
        return cls._checker

    def paintEvent(self, event):
        p = QPainter(self)
        p.scale(self.zoom, self.zoom)
        p.drawTiledPixmap(QRect(0, 0, self.image.width(), self.image.height()), self.checker_pixmap())
        p.drawImage(QPoint(0, 0), self.image)
        if self.floating is not None:
            p.drawImage(self.selection.topLeft(), self.floating_image())
        if self.grid and self.zoom >= 4:
            pen = QPen(QColor(150, 150, 150, 90), 0)
            p.setPen(pen)
            visible = self.visibleRegion().boundingRect()
            x1, y1 = int(visible.left() / self.zoom), int(visible.top() / self.zoom)
            x2 = min(self.image.width(), int(visible.right() / self.zoom) + 1)
            y2 = min(self.image.height(), int(visible.bottom() / self.zoom) + 1)
            for x in range(x1, x2 + 1):
                p.drawLine(x, y1, x, y2)
            for y in range(y1, y2 + 1):
                p.drawLine(x1, y, x2, y)
        if not self.selection.isEmpty():
            pen = QPen(QColor('#2865a8'), 0, Qt.PenStyle.DashLine)
            p.setPen(pen)
            p.setBrush(Qt.BrushStyle.NoBrush)
            if self.selection_shape is not None:
                p.save();p.translate(QPointF(self.selection.topLeft()));p.drawPath(self.selection_shape);p.restore()
            else:p.drawRect(self.selection)
        if self.lasso is not None and len(self.lasso)>1:
            p.setPen(QPen(QColor('#2865a8'),0,Qt.PenStyle.DashLine));p.setBrush(Qt.BrushStyle.NoBrush)
            p.drawPolyline(QPolygonF(self.lasso))
        if self.dragging and self.tool=='text' and self.text_entry is None:
            p.setPen(QPen(QColor('#3c7fb1'),0,Qt.PenStyle.DashLine));p.setBrush(Qt.BrushStyle.NoBrush)
            p.drawRect(QRect(self.start,self.end).normalized())
        p.setPen(QPen(QColor('#798a9a'), 0))
        p.setBrush(QColor('white'))
        side = 5 / self.zoom
        for x, y in ((self.image.width(), self.image.height()),
                     (self.image.width(), self.image.height() / 2),
                     (self.image.width() / 2, self.image.height())):
            p.drawRect(QRectF(x, y, side, side))
        p.end()

    def text_base_font(self):
        f=QFont(self.text_font)
        size=self.text_font.pointSizeF()
        f.setPixelSize(max(1,round(size*96/72) if size>0 else self.text_font.pixelSize()))
        return f

    def text_document(self,text,width,color=None):
        doc=QTextDocument()
        doc.setDocumentMargin(0)
        doc.setDefaultFont(self.text_base_font())
        option=QTextOption();option.setWrapMode(QTextOption.WrapMode.WrapAtWordBoundaryOrAnywhere)
        doc.setDefaultTextOption(option)
        doc.setPlainText(text)
        doc.setTextWidth(max(1,width))
        if color is not None:
            cursor=QTextCursor(doc);cursor.select(QTextCursor.SelectionType.Document)
            fmt=QTextCharFormat();fmt.setForeground(QColor(color));cursor.mergeCharFormat(fmt)
        return doc

    def text_content_height(self,width=None):
        text=self.text_entry.toPlainText() if self.text_entry is not None else ''
        doc=self.text_document(text,self.text_box_size.width() if width is None else width)
        return max(1,math.ceil(doc.size().height()))

    def paint_text(self,image,text):
        rect=QRect(self.text_origin,self.text_box_size)
        p=QPainter(image)
        if self.text_opaque:p.fillRect(rect,self.secondary)
        p.setRenderHint(QPainter.RenderHint.TextAntialiasing,self.antialias)
        p.setClipRect(rect)
        p.translate(QPointF(rect.topLeft()))
        self.text_document(text,rect.width(),self.text_color).drawContents(p,QRectF(0,0,rect.width(),rect.height()))
        p.end()

    def begin_text(self,start,end=None):
        r=QRect(start,end if end is not None else start).normalized()
        W,H=self.image.width(),self.image.height()
        if r.width()<8 or r.height()<8:
            line=math.ceil(self.text_document('',1).size().height())
            w,h=220,max(2*line,30)
        else:
            w,h=r.width(),r.height()
        w,h=max(1,min(w,W)),max(1,min(h,H))
        x,y=max(0,min(r.left(),W-w)),max(0,min(r.top(),H-h))
        self.text_origin=QPoint(x,y);self.text_box_size=QSize(w,h)
        self.text_color=QColor(self.active_color())
        self.text_entry=TextBox(self)
        self.text_entry.editor.textChanged.connect(self.text_changed)
        self.update_text_box();self.text_entry.show();self.text_entry.setFocus()

    def text_changed(self):
        self.update_text_box();self.changed.emit()

    def update_text_box(self):
        if self.text_entry is None:return
        H=self.image.height()
        need=min(H,self.text_content_height())
        if self.text_box_size.height()<need:
            self.text_box_size=QSize(self.text_box_size.width(),need)
            self.text_origin=QPoint(self.text_origin.x(),min(self.text_origin.y(),H-need))
        z,m=self.zoom,TEXT_FRAME
        x,y=round(self.text_origin.x()*z),round(self.text_origin.y()*z)
        w,h=max(1,round(self.text_box_size.width()*z)),max(1,round(self.text_box_size.height()*z))
        editor=self.text_entry.editor
        background=self.secondary.name() if self.text_opaque else 'transparent'
        f=self.text_base_font();f.setPixelSize(max(1,round(f.pixelSize()*z)))
        # The window stylesheet sets a global font, so the editor's font must be set by its own stylesheet.
        family=f.family().replace('"','')
        editor.setStyleSheet(f'QPlainTextEdit {{background:{background};border:0;padding:0;color:{self.text_color.name()};'
                             f'font-family:"{family}";font-size:{f.pixelSize()}px;'
                             f'font-weight:{700 if f.bold() else 400};font-style:{"italic" if f.italic() else "normal"};'
                             f'text-decoration:{" ".join(d for d,on in (("underline",f.underline()),("line-through",f.strikeOut())) if on) or "none"};}}')
        editor.setFont(f)
        self.text_entry.setGeometry(x-m,y-m,w+2*m,h+2*m)
        editor.setGeometry(m,m,w,h)
        self.text_entry.update()

    def cancel_text(self):
        if self.text_entry is not None:
            self.text_entry.hide();self.text_entry.deleteLater();self.text_entry=None;self.setFocus()
            self.update()

    def commit_text(self):
        if self.text_entry is None:return
        text=self.text_entry.toPlainText()
        self.cancel_text()
        if text:
            self.snapshot()
            self.paint_text(self.image,text)
            self.modified()

    def active_color(self):
        return self.secondary if self.right_button else self.primary

    def draw_stroke(self, a, b):
        p = QPainter(self.image)
        use_aa = (getattr(self, 'hardness', 100) < 100) if self.tool in ('eraser', 'brush', 'pencil') else self.antialias
        p.setRenderHint(QPainter.RenderHint.Antialiasing, use_aa and self.tool != 'pencil')
        if self.tool == 'eraser':
            if self.right_button or self.secondary.alpha() == 0:
                color = QColor(0, 0, 0, 0)
                p.setCompositionMode(QPainter.CompositionMode.CompositionMode_Source)
            elif self.secondary.alpha() < 255:
                color = self.secondary
                p.setCompositionMode(QPainter.CompositionMode.CompositionMode_Source)
            else:
                color = self.secondary
        else:
            color = self.active_color()
            if color.alpha() == 0:
                p.setCompositionMode(QPainter.CompositionMode.CompositionMode_Source)
        width = self.stroke_width
        if self.tool == 'eraser':
            width = max(1, width)
            shape = getattr(self, 'eraser_shape', 'round')
            cap = Qt.PenCapStyle.RoundCap if shape == 'round' else Qt.PenCapStyle.SquareCap
        else:
            cap = Qt.PenCapStyle.SquareCap if self.tool=='pencil' or self.brush_style == 'Square' else Qt.PenCapStyle.RoundCap
        hardness=getattr(self,'hardness',100)
        if hardness<100 and self.tool in ('brush','pencil','eraser') and not (self.tool=='brush' and self.brush_style=='Airbrush'):
            from .brushes import soft_stroke
            square=self.tool=='pencil' or (self.tool=='eraser' and getattr(self,'eraser_shape','round')=='square') or (self.tool=='brush' and self.brush_style=='Square')
            soft_stroke(p,a,b,color,width,hardness,square);p.end();return
        p.setPen(QPen(color, width, Qt.PenStyle.SolidLine, cap, Qt.PenJoinStyle.RoundJoin))
        if self.brush_style == 'Airbrush' and self.tool == 'brush':
            p.setPen(QPen(color, 1))
            radius = max(3, width * 2)
            steps = max(1, int(math.hypot(b.x() - a.x(), b.y() - a.y()) / 2))
            for step in range(steps + 1):
                cx = a.x() + (b.x() - a.x()) * step / steps
                cy = a.y() + (b.y() - a.y()) * step / steps
                for _ in range(max(8, width * 4)):
                    angle, r = random.random() * math.tau, math.sqrt(random.random()) * radius
                    p.drawPoint(QPointF(cx + math.cos(angle) * r, cy + math.sin(angle) * r))
        else:
            p.drawLine(a, b)
            if a == b:
                p.drawPoint(a)
        p.end()

    def draw_shape(self, end, shift=False):
        self.image = self.before.copy()
        a, b = self.start, QPoint(end)
        if shift:
            dx, dy = b.x() - a.x(), b.y() - a.y()
            if self.tool == 'line':
                radius = math.hypot(dx, dy)
                angle = round(math.atan2(dy, dx) / (math.pi / 4)) * math.pi / 4
                b = QPoint(a.x() + round(radius * math.cos(angle)), a.y() + round(radius * math.sin(angle)))
            else:
                length = max(abs(dx), abs(dy))
                b = QPoint(a.x() + (length if dx >= 0 else -length), a.y() + (length if dy >= 0 else -length))
        r = QRectF(QPointF(a), QPointF(b)).normalized()
        sigma=self.stroke_width*.5*(1-self.hardness/100)
        layer=None
        if sigma>0:
            margin=math.ceil(self.stroke_width/2+3*sigma+2)
            bounds=r.adjusted(-margin,-margin,margin,margin)
            if self.tool=='curve':bounds=bounds.adjusted(0,-r.height()*.7,0,r.height()*.7)
            region=bounds.toAlignedRect().intersected(self.image.rect().adjusted(-margin,-margin,margin,margin))
            if region.isEmpty():return
            layer=blank(region.width(),region.height(),Qt.GlobalColor.transparent)
        p = QPainter(layer if layer is not None else self.image)
        if layer is not None:p.translate(-region.x(),-region.y())
        p.setRenderHint(QPainter.RenderHint.Antialiasing, self.antialias)
        p.setPen(QPen(self.active_color(), self.stroke_width, self.outline_style,
                      Qt.PenCapStyle.FlatCap, Qt.PenJoinStyle.RoundJoin) if self.outline else Qt.PenStyle.NoPen)
        p.setBrush((self.primary if self.right_button else self.secondary) if self.fill else Qt.BrushStyle.NoBrush)
        if self.tool == 'line':
            p.setPen(QPen(self.active_color(), self.stroke_width,self.outline_style) if self.outline else Qt.PenStyle.NoPen)
            p.drawLine(a, b)
        elif self.tool == 'rectangle':
            p.drawRect(r)
        elif self.tool == 'rounded':
            p.drawRoundedRect(r, 12, 12)
        elif self.tool == 'ellipse':
            p.drawEllipse(r)
        elif self.tool in ('triangle', 'righttriangle', 'trapezoid', 'diamond', 'pentagon', 'hexagon', 'star','star4','star6'):
            if self.tool == 'triangle':
                points = [QPointF(r.center().x(), r.top()), r.bottomRight(), r.bottomLeft()]
            elif self.tool == 'righttriangle':
                points = [r.topLeft(), r.bottomRight(), r.bottomLeft()]
            elif self.tool == 'trapezoid':
                points = [QPointF(r.left()+r.width()*.25,r.top()),QPointF(r.right()-r.width()*.25,r.top()),r.bottomRight(),r.bottomLeft()]
            elif self.tool == 'diamond':
                points = [QPointF(r.center().x(), r.top()), QPointF(r.right(), r.center().y()),
                          QPointF(r.center().x(), r.bottom()), QPointF(r.left(), r.center().y())]
            else:
                n = {'pentagon': 5, 'hexagon': 6, 'star': 10,'star4':8,'star6':12}[self.tool]
                points = []
                for i in range(n):
                    theta = -math.pi / 2 + i * math.tau / n
                    radius = .42 if self.tool.startswith('star') and i % 2 else 1
                    points.append(QPointF(r.center().x() + math.cos(theta) * r.width() / 2 * radius,
                                          r.center().y() + math.sin(theta) * r.height() / 2 * radius))
            p.drawPolygon(QPolygonF(points))
        elif self.tool=='curve':
            path=QPainterPath(QPointF(a))
            path.cubicTo(QPointF(a.x()+r.width()*.3,a.y()-r.height()*.7),QPointF(b.x()-r.width()*.3,b.y()+r.height()*.7),QPointF(b))
            p.setBrush(Qt.BrushStyle.NoBrush);p.drawPath(path)
        elif self.tool=='polygon':
            p.drawPolygon(QPolygonF([QPointF(r.left()+r.width()*.25,r.top()),QPointF(r.right()-r.width()*.2,r.top()),QPointF(r.right()-r.width()*.4,r.center().y()),QPointF(r.right(),r.center().y()),r.bottomRight(),r.bottomLeft()]))
        elif self.tool in ('speech','ovalspeech','cloud'):
            path=QPainterPath();body=QRectF(r.left(),r.top(),r.width(),r.height()*.75)
            if self.tool=='speech':path.addRoundedRect(body,4,4)
            elif self.tool=='ovalspeech':path.addEllipse(body)
            else:
                for i in range(10):
                    angle=i*math.tau/10
                    path.addEllipse(QRectF(body.center().x()+math.cos(angle)*body.width()*.32-body.width()*.2,body.center().y()+math.sin(angle)*body.height()*.32-body.height()*.24,body.width()*.4,body.height()*.48))
                path.setFillRule(Qt.FillRule.WindingFill)
            tail=QPainterPath(QPointF(r.left()+r.width()*.25,r.top()+r.height()*.6))
            tail.lineTo(QPointF(r.left()+r.width()*.2,r.bottom()));tail.lineTo(QPointF(r.left()+r.width()*.5,r.top()+r.height()*.68));tail.closeSubpath()
            p.drawPath(path.united(tail).simplified())
        elif self.tool.startswith('arrow'):
            w,h=r.width(),r.height()
            p.save()
            if self.tool=='arrowleft':p.translate(r.right(),r.bottom());p.rotate(180)
            elif self.tool=='arrowup':p.translate(r.left(),r.bottom());p.rotate(-90);w,h=h,w
            elif self.tool=='arrowdown':p.translate(r.right(),r.top());p.rotate(90);w,h=h,w
            else:p.translate(r.topLeft())
            p.drawPolygon(QPolygonF([QPointF(0,h*.3),QPointF(w*.6,h*.3),QPointF(w*.6,0),QPointF(w,h*.5),QPointF(w*.6,h),QPointF(w*.6,h*.7),QPointF(0,h*.7)]))
            p.restore()
        p.end()
        if layer is not None:
            from .brushes import feather_shape
            p=QPainter(self.image)
            p.drawImage(region.topLeft(),feather_shape(layer,sigma))
            p.end()

    def resize_handle_at(self, position):
        w,h=self.image.width()*self.zoom,self.image.height()*self.zoom
        for x,y,axes in ((w,h,(True,True)),(w,h/2,(True,False)),(w/2,h,(False,True))):
            if QRectF(x-3,y-3,11,11).contains(QPointF(position)):return axes
        return None

    def update_pointer(self, position=None):
        axes=self.resize_axes if self.resize_drag else self.resize_handle_at(position) if position is not None else None
        if axes is not None:
            cursor=Qt.CursorShape.SizeFDiagCursor if all(axes) else Qt.CursorShape.SizeHorCursor if axes[0] else Qt.CursorShape.SizeVerCursor
        else:
            cursor=Qt.CursorShape.SizeAllCursor if self.tool=='select' and (self.moving or position is not None and self.selection.contains(QPoint(int(position.x()/self.zoom),int(position.y()/self.zoom)))) else self.tool_cursor()
        self.setCursor(cursor)

    def leaveEvent(self,event):
        self.position.emit('')
        self.update_pointer();super().leaveEvent(event)

    def dragEnterEvent(self, event):
        if event.mimeData().hasUrls():
            event.acceptProposedAction()
        else:
            super().dragEnterEvent(event)

    def dragMoveEvent(self, event):
        if event.mimeData().hasUrls():
            event.acceptProposedAction()
        else:
            super().dragMoveEvent(event)

    def dropEvent(self, event):
        win = self.window()
        if hasattr(win, 'handle_drop_event'):
            win.handle_drop_event(event)
        else:
            super().dropEvent(event)

    def mousePressEvent(self, event):
        if event.button() not in (Qt.MouseButton.LeftButton, Qt.MouseButton.RightButton):
            return
        self.setFocus()
        point = self.document_point(event)
        self.start = self.last = self.end = point
        self.right_button = event.button() == Qt.MouseButton.RightButton
        w, h = self.image.width(), self.image.height()
        axes=self.resize_handle_at(event.position())
        if axes is not None and event.button()==Qt.MouseButton.LeftButton:
            self.commit_selection()
            self.resize_drag=True;self.resize_axes=axes;self.original_size=(w,h);self.resize_origin=QPointF(event.position())
            self.resize_preview_changed.emit((w,h))
            self.update_pointer(event.position());return
        if not self.image.rect().contains(point):return
        self.dragging = True
        if self.tool == 'select':
            if self.selection.contains(point):
                self.lift_selection()
                self.moving = True
                self.move_origin = QPoint(self.selection.topLeft())
                self.update_pointer(event.position())
            else:
                self.commit_selection()
                if self.selection_mode=='free':self.lasso=[QPointF(point)]
                else:self.selection = QRect(point, point)
        elif self.tool == 'picker':
            self.picked.emit(self.image.pixelColor(point), self.right_button)
        elif self.tool == 'magnifier':
            new = round(self.zoom * 100 * (.5 if self.right_button else 2))
            self.set_zoom(max(25, min(800, new)))
            workspace = self.parentWidget().parentWidget() if (self.parentWidget() and hasattr(self.parentWidget(), 'parentWidget')) else None
            if workspace and isinstance(workspace, QScrollArea):
                vp = workspace.viewport()
                tx = point.x() * self.zoom + 6 - (vp.width() / 2)
                ty = point.y() * self.zoom + 6 - (vp.height() / 2)
                workspace.horizontalScrollBar().setValue(round(tx))
                workspace.verticalScrollBar().setValue(round(ty))
        elif self.tool == 'text':
            had_text=self.text_entry is not None
            self.commit_selection()
            if had_text:self.dragging=False

        else:
            self.commit_selection()
            self.snapshot()
            self.before = self.image.copy()
            if self.tool == 'bucket':
                if self.bucket_fill and fill_region(self.image, point, self.active_color()):
                    self.modified()
            elif self.tool in ('brush', 'pencil', 'eraser'):
                self.draw_stroke(point, point)
                self.modified()
        self.update()

    def mouseMoveEvent(self, event):
        self.update_pointer(event.position())
        if self.resize_drag:
            delta=(event.position()-self.resize_origin)/self.zoom
            w=max(1,self.original_size[0]+round(delta.x())) if self.resize_axes[0] else self.original_size[0]
            h=max(1,self.original_size[1]+round(delta.y())) if self.resize_axes[1] else self.original_size[1]
            if w*h<=MAX_PIXELS:self.resize_preview_changed.emit((w,h))
            return
        point = self.document_point(event)
        self.position.emit(f'{point.x()}, {point.y()} px')
        if not self.dragging:
            return
        self.end = point
        if self.tool == 'select':
            if self.moving:
                self.selection.moveTopLeft(self.move_origin + point - self.start)
            elif self.lasso is not None:
                self.lasso.append(QPointF(max(0,min(self.image.width(),point.x())),max(0,min(self.image.height(),point.y()))))
            else:
                self.selection = QRect(self.start, point).normalized().intersected(self.image.rect())
        elif self.tool in ('brush', 'pencil', 'eraser'):
            self.draw_stroke(self.last, point)
            self.modified()
        elif self.tool not in ('bucket', 'picker', 'magnifier', 'text'):
            self.draw_shape(point, bool(event.modifiers() & Qt.KeyboardModifier.ShiftModifier))
            self.modified()
        self.last = point
        self.update()

    def mouseReleaseEvent(self, event):
        if self.dragging and self.document_point(event) != self.last:
            self.mouseMoveEvent(event)
        if self.dragging and self.tool=='text' and self.text_entry is None:
            self.dragging=False
            self.begin_text(self.start,self.end)
            self.update()
            return
        if self.lasso is not None:
            self.finish_lasso()
        if self.resize_drag:
            delta=(event.position()-self.resize_origin)/self.zoom
            w = max(1, self.original_size[0]+round(delta.x())) if self.resize_axes[0] else self.original_size[0]
            h = max(1, self.original_size[1]+round(delta.y())) if self.resize_axes[1] else self.original_size[1]
            self.resize_drag = False
            self.resize_preview_changed.emit(None)
            if (w,h)!=self.original_size and w * h <= MAX_PIXELS:
                self.resize_document(w, h, scale=False)
        was_moving = self.moving
        self.dragging = False
        self.moving = False
        self.before = None
        self.update_pointer(event.position())
        self.selection_changed.emit()
        if was_moving:
            self.modified()
        else:
            self.update()

    def commit_selection(self):
        self.commit_text()
        if self.floating is not None:
            p = QPainter(self.image)
            p.drawImage(self.selection.topLeft(), self.floating_image())
            p.end()
            self.floating = None
            self.modified()
        self.selection = QRect()
        self.selection_changed.emit()
        self.update()

    def composite(self):
        image = self.image.copy()
        if self.text_entry is not None and self.text_entry.toPlainText():
            self.paint_text(image,self.text_entry.toPlainText())
        if self.floating is not None:
            p = QPainter(image)
            p.drawImage(self.selection.topLeft(), self.floating_image())
            p.end()
        return image

    def copy(self):
        self.commit_text()
        source = self.floating if self.floating is not None else self.image
        image = source.copy() if self.floating is not None or self.selection.isEmpty() else source.copy(self.selection)
        QApplication.clipboard().setImage(image)

    def delete_selection(self):
        if self.selection.isEmpty():
            return
        self.snapshot()
        if self.floating is None:
            p = QPainter(self.image)
            if self.secondary.alpha() == 0:
                p.setCompositionMode(QPainter.CompositionMode.CompositionMode_Clear)
                if self.selection_shape is not None:
                    p.translate(QPointF(self.selection.topLeft()));p.fillPath(self.selection_shape, Qt.GlobalColor.transparent)
                else:p.fillRect(self.selection, Qt.GlobalColor.transparent)
            else:
                if self.selection_shape is not None:
                    p.translate(QPointF(self.selection.topLeft()));p.fillPath(self.selection_shape,self.secondary)
                else:p.fillRect(self.selection, self.secondary)
            p.end()
        self.floating = None
        self.selection = QRect()
        self.modified()

    def cut(self):
        if self.selection.isEmpty():
            self.selection = self.image.rect()
        self.copy()
        self.delete_selection()

    def paste(self, source=None):
        source=clipboard_image() if source is None else source
        if source.isNull() or source.width()*source.height()>MAX_PIXELS:return False
        w,h=max(source.width(),self.image.width()),max(source.height(),self.image.height())
        if w*h>MAX_PIXELS:return False
        self.commit_selection();self.snapshot()
        if (w,h)!=(self.image.width(),self.image.height()):
            expanded=blank(w,h,self.secondary)
            p=QPainter(expanded);p.drawImage(0,0,self.image);p.end();self.image=expanded
        self.floating=source.convertToFormat(QImage.Format.Format_ARGB32)
        self.floating.setDevicePixelRatio(1)
        self.selection=source.rect();self.tool='select'
        self.sync_size();self.update_pointer();self.modified();return True

    def crop(self):
        if not self.selection.isEmpty():
            r = QRect(self.selection).intersected(self.image.rect())
            if not r.isEmpty():
                result = self.composite().copy(r)
                self.set_image(result)

    def resize_document(self, w, h, scale=True):
        if w * h > MAX_PIXELS:
            raise ValueError('Image exceeds the 32 megapixel limit.')
        self.commit_selection()
        if scale:
            result = self.image.scaled(w, h, Qt.AspectRatioMode.IgnoreAspectRatio,
                                       Qt.TransformationMode.SmoothTransformation)
        else:
            result = blank(w, h, self.secondary)
            p = QPainter(result)
            p.drawImage(0, 0, self.image)
            p.end()
        self.set_image(result)

    def lift_selection(self):
        if self.floating is None and not self.selection.isEmpty():
            self.snapshot()
            if self.selection_shape is None:
                self.floating=self.image.copy(self.selection)
                p=QPainter(self.image)
                if self.secondary.alpha() == 0:
                    p.setCompositionMode(QPainter.CompositionMode.CompositionMode_Clear)
                    p.fillRect(self.selection, Qt.GlobalColor.transparent)
                else:p.fillRect(self.selection,self.secondary)
                p.end()
            else:
                piece=blank(self.selection.width(),self.selection.height(),Qt.GlobalColor.transparent)
                p=QPainter(piece);p.setClipPath(self.selection_shape)
                p.drawImage(QPoint(0,0),self.image,self.selection);p.end()
                self.floating=piece
                p=QPainter(self.image);p.translate(QPointF(self.selection.topLeft()))
                if self.secondary.alpha() == 0:
                    p.setCompositionMode(QPainter.CompositionMode.CompositionMode_Clear)
                    p.fillPath(self.selection_shape, Qt.GlobalColor.transparent)
                else:p.fillPath(self.selection_shape,self.secondary)
                p.end()
            self.modified()

    def floating_image(self):
        # Transparent selection: pixels in Color 2 (background) are not carried along.
        if not self.transparent_selection:return self.floating
        image=self.floating.copy()
        mask=image.createMaskFromColor(QColor(self.secondary).rgb(),Qt.MaskMode.MaskOutColor)
        alpha=QImage(image.size(),QImage.Format.Format_ARGB32);alpha.fill(Qt.GlobalColor.white)
        alpha.setAlphaChannel(mask.convertToFormat(QImage.Format.Format_Grayscale8))
        p=QPainter(image);p.setCompositionMode(QPainter.CompositionMode.CompositionMode_DestinationIn)
        p.drawImage(0,0,alpha);p.end()
        return image

    def finish_lasso(self):
        points,self.lasso=self.lasso,None
        if len(points)<3:return
        path=QPainterPath();path.addPolygon(QPolygonF(points));path.closeSubpath()
        bounds=path.boundingRect().toAlignedRect().intersected(self.image.rect())
        if bounds.width()<1 or bounds.height()<1:return
        self.selection=bounds
        self.selection_shape=path.translated(-QPointF(bounds.topLeft()))
        self.selection_changed.emit()

    def invert_selection(self):
        if self.selection.isEmpty():return self.select_everything()
        self.commit_text()
        if self.floating is not None:   # place the moved piece first, like MS Paint
            p=QPainter(self.image);p.drawImage(self.selection.topLeft(),self.floating_image());p.end()
            self.floating=None;self.modified()
        current=QPainterPath()
        if self.selection_shape is not None:current=self.selection_shape.translated(QPointF(self.selection.topLeft()))
        else:current.addRect(QRectF(self.selection))
        everything=QPainterPath();everything.addRect(QRectF(self.image.rect()))
        self.selection=self.image.rect()
        self.selection_shape=everything.subtracted(current)
        self.selection_changed.emit();self.update()

    def select_everything(self):
        self.commit_selection();self.selection=self.image.rect();self.update()

    def tool_cursor(self):
        tool=self.tool
        if tool=='text':return QCursor(Qt.CursorShape.IBeamCursor)
        if tool in ('brush','pencil','eraser'):
            if tool=='eraser':size,shape=max(1,self.stroke_width),getattr(self, 'eraser_shape', 'round')
            elif tool=='pencil':size,shape=self.stroke_width,'square'
            elif self.brush_style=='Airbrush':size,shape=max(3,self.stroke_width*2)*2,'round'
            else:size,shape=self.stroke_width,'square' if self.brush_style=='Square' else 'round'
            size=min(128,round(size*self.zoom))
            if size<5:return QCursor(Qt.CursorShape.CrossCursor)
            key=(tool,shape,size)
            if key not in self._cursor_cache:
                pix=QPixmap(size+2,size+2);pix.fill(Qt.GlobalColor.transparent);p=QPainter(pix)
                for color,inset in ((QColor('white'),0),(QColor('black'),1)):
                    p.setPen(QPen(color,1));p.setBrush(Qt.BrushStyle.NoBrush)
                    r=QRectF(inset+0.5,inset+0.5,size+1-2*inset,size+1-2*inset)
                    p.drawRect(r) if shape=='square' else p.drawEllipse(r)
                p.end();self._cursor_cache[key]=QCursor(pix,(size+2)//2,(size+2)//2)
            return self._cursor_cache[key]
        hotspots={'pencil':(0,19),'picker':(1,19),'bucket':(1,17),'magnifier':(7,6)}
        if tool in hotspots:
            if tool not in self._cursor_cache:
                pix=tool_icon(tool).pixmap(QSize(20,20))
                self._cursor_cache[tool]=QCursor(pix,*hotspots[tool])
            return self._cursor_cache[tool]
        if tool=='select':
            key=('select',self.selection_mode)
            if key not in self._cursor_cache:
                pix=QPixmap(24,26);pix.fill(Qt.GlobalColor.transparent);p=QPainter(pix)
                p.setRenderHint(QPainter.RenderHint.Antialiasing)
                arrow=QPolygonF([QPointF(*xy) for xy in ((0.5,0.5),(0.5,15),(4,11.5),(6.5,17),(8.5,16),(6,10.5),(11,10.5))])
                p.setPen(QPen(QColor('black'),1));p.setBrush(QColor('white'));p.drawPolygon(arrow)
                p.setRenderHint(QPainter.RenderHint.Antialiasing,False)
                p.setPen(QPen(QColor('black'),1,Qt.PenStyle.DotLine));p.setBrush(Qt.BrushStyle.NoBrush)
                if self.selection_mode=='free':
                    p.setRenderHint(QPainter.RenderHint.Antialiasing)
                    blob=QPainterPath(QPointF(13,15));blob.cubicTo(QPointF(9,14),QPointF(10,24),QPointF(16,24))
                    blob.cubicTo(QPointF(23,24),QPointF(23,19),QPointF(19,18));blob.cubicTo(QPointF(17,15),QPointF(16,13),QPointF(13,15))
                    p.drawPath(blob)
                else:p.drawRect(12,15,10,8)
                p.end();self._cursor_cache[key]=QCursor(pix,0,0)
            return self._cursor_cache[key]
        return QCursor(Qt.CursorShape.CrossCursor)

    def change_width(self, delta):
        width=max(1,min(200,self.stroke_width+delta))
        win=self.window()
        if hasattr(win,'set_width'):win.set_width(width)
        else:self.stroke_width=width;self.update_pointer()

    def keyPressEvent(self, event):
        if event.matches(QKeySequence.StandardKey.Undo) or (event.key() == Qt.Key.Key_Z and event.modifiers() == Qt.KeyboardModifier.ControlModifier):
            self.undo()
            event.accept()
            return
        if event.matches(QKeySequence.StandardKey.Redo) or (event.key() == Qt.Key.Key_Y and event.modifiers() == Qt.KeyboardModifier.ControlModifier) or (event.key() == Qt.Key.Key_Z and event.modifiers() == (Qt.KeyboardModifier.ControlModifier | Qt.KeyboardModifier.ShiftModifier)):
            self.redo()
            event.accept()
            return
        if event.modifiers() == Qt.KeyboardModifier.ControlModifier:
            if event.key() == Qt.Key.Key_C:
                self.copy()
                event.accept()
                return
            elif event.key() == Qt.Key.Key_X:
                self.cut()
                event.accept()
                return
            elif event.key() == Qt.Key.Key_V:
                win = self.window()
                if hasattr(win, 'paste'): win.paste()
                event.accept()
                return
            elif event.key() == Qt.Key.Key_A:
                win = self.window()
                if hasattr(win, 'select_all'): win.select_all()
                event.accept()
                return
        if event.modifiers()==Qt.KeyboardModifier.NoModifier and self.tool in ('brush','pencil','eraser')+SHAPE_TOOLS:
            if event.key() in (Qt.Key.Key_BracketLeft,Qt.Key.Key_BracketRight):
                self.change_width(1 if event.key()==Qt.Key.Key_BracketRight else -1)
                event.accept()
                return
        arrows={Qt.Key.Key_Left:(-1,0),Qt.Key.Key_Right:(1,0),Qt.Key.Key_Up:(0,-1),Qt.Key.Key_Down:(0,1)}
        if event.key() in arrows and self.tool=='select' and not self.selection.isEmpty() and event.modifiers() in (Qt.KeyboardModifier.NoModifier,Qt.KeyboardModifier.ShiftModifier):
            self.lift_selection();dx,dy=arrows[event.key()];step=10 if event.modifiers() & Qt.KeyboardModifier.ShiftModifier else 1
            self.selection.translate(dx*step,dy*step);self.modified()
        elif event.key() == Qt.Key.Key_Escape:
            self.commit_selection()
        elif event.key() in (Qt.Key.Key_Delete, Qt.Key.Key_Backspace):
            self.delete_selection()
        else:
            super().keyPressEvent(event)


