class Ruler(QWidget):
    def __init__(self, area, vertical=False):
        super().__init__(area)
        self.area=area;self.vertical=vertical
        self.setAttribute(Qt.WidgetAttribute.WA_TransparentForMouseEvents)

    def paintEvent(self,event):
        p=QPainter(self)
        dark = getattr(self.window(), 'dark_mode', True) if self.window() else True
        bg_col = QColor('#242424') if dark else QColor('#ededed')
        border_col = QColor('#383838') if dark else QColor('#b9b9b9')
        text_col = QColor('#9a9996') if dark else QColor('#666666')
        pointer_col = QColor('#3584e4') if dark else QColor('#db6565')
        p.fillRect(self.rect(), bg_col)
        p.setPen(border_col);p.drawRect(self.rect().adjusted(0,0,-1,-1))
        p.setFont(QFont('Arial',8))
        zoom=self.area.canvas.zoom
        origin=self.area.canvas.mapTo(self.area.viewport(),QPoint()).y() if self.vertical else self.area.canvas.mapTo(self.area.viewport(),QPoint()).x()
        length=self.height() if self.vertical else self.width()
        step=10
        while step*zoom<7:step*=2
        first=math.floor(-origin/zoom/step)*step
        for value in range(first,int((length-origin)/zoom)+step,step):
            pixel=round(origin+value*zoom)
            major=value%(step*10)==0;middle=value%(step*5)==0
            tick=10 if major else 7 if middle else 4
            p.setPen(text_col)
            if self.vertical:
                p.drawLine(self.width()-tick,pixel,self.width()-1,pixel)
                if major:
                    p.save();p.translate(11,pixel+3);p.rotate(-90);p.drawText(0,0,tr(str(value)));p.restore()
            else:
                p.drawLine(pixel,self.height()-tick,pixel,self.height()-1)
                if major:p.drawText(pixel+3,11,tr(str(value)))
        point=self.area.pointer
        if point is not None:
            pixel=round(origin+(point.y() if self.vertical else point.x())*zoom)
            p.setPen(QPen(pointer_col,1))
            if self.vertical:p.drawLine(0,pixel,self.width(),pixel)
            else:p.drawLine(pixel,0,pixel,self.height())
        p.end()


class Workspace(QScrollArea):
    def __init__(self,canvas):
        super().__init__()
        self.canvas=canvas;self.pointer=None;self.rulers_visible=True
        self.setFrameShape(QFrame.Shape.NoFrame)
        self.setAlignment(Qt.AlignmentFlag.AlignLeft|Qt.AlignmentFlag.AlignTop)
        self.apply_theme(True)
        self.sheet=QWidget()
        canvas.setParent(self.sheet);canvas.move(6,6)
        canvas.setStyleSheet("background:transparent;")
        self.sheet.setFixedSize(canvas.width()+12,canvas.height()+12)
        self.setWidget(self.sheet)
        self.sheet.setAutoFillBackground(False)
        self.horizontal=Ruler(self);self.vertical=Ruler(self,True)
        self.setViewportMargins(25,22,0,0)
        self.horizontalScrollBar().valueChanged.connect(self.update_rulers)
        self.verticalScrollBar().valueChanged.connect(self.update_rulers)
        self.canvas.zoomed.connect(self.update_rulers)
        self.canvas.changed.connect(self.update_rulers)
        self.canvas.position.connect(self.pointer_changed)
        self.apply_theme(True)
        self.resize_overlay=ResizeOverlay(self)
        self.canvas.resize_preview_changed.connect(self.resize_overlay.set_target)

    def apply_theme(self, dark):
        if dark:
            self.setStyleSheet('QScrollArea {border:0;background:#1d1d1d;} QScrollBar {background:#1e1e1e;}')
        else:
            self.setStyleSheet('QScrollArea {border:0;background:#dedede;} QScrollBar {background:#ededed;}')
        if hasattr(self, 'horizontal'):
            self.horizontal.update()
            self.vertical.update()

    def resizeEvent(self,event):
        super().resizeEvent(event)
        if hasattr(self,'horizontal'):self.position_rulers()

    def position_rulers(self):
        r=self.viewport().geometry()
        self.horizontal.setGeometry(r.x(),0,r.width(),22)
        self.vertical.setGeometry(0,r.y(),25,r.height())
        self.update_rulers()

    def update_rulers(self,*args):
        self.sheet.setFixedSize(self.canvas.width()+12,self.canvas.height()+12)
        self.horizontal.update();self.vertical.update()

    def pointer_changed(self,text):
        try:
            x,y=text.replace(' px','').split(',')
            self.pointer=QPoint(int(x),int(y))
        except ValueError:
            self.pointer=None
        self.update_rulers()

    def wheelEvent(self, event):
        if event.modifiers() & Qt.KeyboardModifier.ControlModifier:
            delta = event.angleDelta().y()
            if delta != 0:
                levels = [25, 50, 100, 200, 300, 400, 500, 600, 700, 800]
                current = round(self.canvas.zoom * 100)
                if delta > 0:
                    candidates = [lvl for lvl in levels if lvl > current]
                    new_zoom = candidates[0] if candidates else 800
                else:
                    candidates = [lvl for lvl in levels if lvl < current]
                    new_zoom = candidates[-1] if candidates else 25
                viewport_pos = event.position()
                old_zoom = self.canvas.zoom
                doc_x = (viewport_pos.x() + self.horizontalScrollBar().value() - 6) / old_zoom
                doc_y = (viewport_pos.y() + self.verticalScrollBar().value() - 6) / old_zoom
                self.canvas.set_zoom(new_zoom)
                new_zoom_factor = self.canvas.zoom
                new_scroll_x = doc_x * new_zoom_factor + 6 - viewport_pos.x()
                new_scroll_y = doc_y * new_zoom_factor + 6 - viewport_pos.y()
                self.horizontalScrollBar().setValue(round(new_scroll_x))
                self.verticalScrollBar().setValue(round(new_scroll_y))
                event.accept()
                return
        super().wheelEvent(event)

    def dragEnterEvent(self, event):
        if event.mimeData().hasUrls():
            event.acceptProposedAction()
        else:
            super().dragEnterEvent(event)

    def dropEvent(self, event):
        win = self.window()
        if hasattr(win, 'handle_drop_event'):
            win.handle_drop_event(event)
        else:
            super().dropEvent(event)

    def show_rulers(self,show):
        self.rulers_visible=show
        self.setViewportMargins(25 if show else 0,22 if show else 0,0,0)
        self.horizontal.setVisible(show);self.vertical.setVisible(show)
        self.position_rulers()


class RibbonScrollArea(QScrollArea):
    def __init__(self,ribbon):
        super().__init__()
        self.setFrameShape(QFrame.Shape.NoFrame);self.setWidgetResizable(True)
        self.setVerticalScrollBarPolicy(Qt.ScrollBarPolicy.ScrollBarAlwaysOff)
        self.setHorizontalScrollBarPolicy(Qt.ScrollBarPolicy.ScrollBarAsNeeded)
        self.setWidget(ribbon);self.setFixedHeight(ribbon.height())
        self.apply_theme(True)

    def apply_theme(self, dark):
        surface='#282828' if dark else '#f0f0f0'
        track='#202020' if dark else '#e4e4e4'
        handle='#656565' if dark else '#a0a0a0'
        self.setStyleSheet(f"QScrollArea {{background:{surface};}} QScrollBar:horizontal {{background:{track};height:12px;}} QScrollBar::handle:horizontal {{background:{handle};min-width:20px;}} QScrollBar::add-line:horizontal,QScrollBar::sub-line:horizontal {{width:0;}}")
        self.viewport().setStyleSheet(f'background:{surface};')

    def resizeEvent(self,event):
        super().resizeEvent(event)
        height=self.widget().height()+(12 if max(self.widget().minimumSizeHint().width(),self.widget().minimumWidth())>self.viewport().width() else 0)
        if self.height()!=height:self.setFixedHeight(height)


def symbolic_document_icon(color):
    pix=QPixmap(20,20);pix.fill(Qt.GlobalColor.transparent)
    p=QPainter(pix);p.setRenderHint(QPainter.RenderHint.Antialiasing)
    glyph(p,'document',QRectF(0,0,20,20),color);p.end()
    return QIcon(pix)


def make_header_icon(name, color='#ffffff', size=20):
    pix = QPixmap(size, size)
    pix.fill(Qt.GlobalColor.transparent)
    p = QPainter(pix)
    p.setRenderHint(QPainter.RenderHint.Antialiasing, True)
    pen = QPen(QColor(color), 1.8, Qt.PenStyle.SolidLine, Qt.PenCapStyle.RoundCap, Qt.PenJoinStyle.RoundJoin)
    p.setPen(pen)
    p.setBrush(Qt.BrushStyle.NoBrush)
    if name == 'save':
        p.drawRoundedRect(QRectF(3.5, 3.5, 13, 13), 2, 2)
        p.fillRect(QRectF(6, 4, 8, 5), QColor(color))
        p.drawRect(QRectF(6, 11, 8, 5))
    elif name == 'undo':
        path = QPainterPath(QPointF(6, 6))
        path.lineTo(3.5, 9.5); path.lineTo(6, 13); p.drawPath(path)
        path2 = QPainterPath(QPointF(4, 9.5))
        path2.cubicTo(QPointF(9, 4), QPointF(15, 6), QPointF(16, 14.5)); p.drawPath(path2)
    elif name == 'redo':
        path = QPainterPath(QPointF(14, 6))
        path.lineTo(16.5, 9.5); path.lineTo(14, 13); p.drawPath(path)
        path2 = QPainterPath(QPointF(16, 9.5))
        path2.cubicTo(QPointF(11, 4), QPointF(5, 6), QPointF(4, 14.5)); p.drawPath(path2)
    elif name == 'magnifier':
        glyph(p,'magnifier',QRectF(1,1,size-2,size-2),color)
    elif name == 'menu':
        p.drawLine(QPointF(4, 5.5), QPointF(16, 5.5))
        p.drawLine(QPointF(4, 10), QPointF(16, 10))
        p.drawLine(QPointF(4, 14.5), QPointF(16, 14.5))
    elif name == 'minimize':
        p.drawLine(QPointF(5, 10), QPointF(15, 10))
    elif name == 'maximize':
        p.drawRoundedRect(QRectF(4.5, 4.5, 11, 11), 1.5, 1.5)
    elif name == 'restore':
        p.drawRoundedRect(QRectF(6.5, 3.5, 9, 9), 1, 1)
        p.drawRoundedRect(QRectF(4.5, 7.5, 9, 9), 1, 1)
    elif name == 'close':
        p.drawLine(QPointF(5.5, 5.5), QPointF(14.5, 14.5))
        p.drawLine(QPointF(14.5, 5.5), QPointF(5.5, 14.5))
    p.end()
    icon = QIcon(pix)
    pix_dis = QPixmap(size, size)
    pix_dis.fill(Qt.GlobalColor.transparent)
    p2 = QPainter(pix_dis)
    p2.setOpacity(0.35)
    p2.drawPixmap(0, 0, pix)
    p2.end()
    icon.addPixmap(pix_dis, QIcon.Mode.Disabled)
    return icon


