class MirrorRibbonButton(ReferenceRibbonButton):
    """A Text-tab copy of a Home-tab ribbon button that shows the twin's live state."""
    def __init__(self,parent,twin,x_offset):
        r=twin.source_rect
        super().__init__(parent,(r.x(),r.y(),r.width(),r.height()),twin.text(),None,twin.isCheckable(),twin.default_checked,twin.default_enabled)
        self.twin=twin;self.move(r.x()+x_offset,r.y())
        self.color_rect=twin.color_rect;self.reference_color=twin.reference_color
        self.setToolTip(tr(twin.toolTip()))
        self.clicked.connect(twin.click)

    def paintEvent(self,event):
        if self.isEnabled()!=self.twin.isEnabled():self.setEnabled(self.twin.isEnabled())
        if self.isCheckable() and self.isChecked()!=self.twin.isChecked():self.setChecked(self.twin.isChecked())
        self.color=self.twin.color
        super().paintEvent(event)

    def mousePressEvent(self,event):
        if self.twin.color is not None and event.button()==Qt.MouseButton.RightButton:
            self.twin.mousePressEvent(event)
        else:super().mousePressEvent(event)
        self.parentWidget().update()

    def mouseReleaseEvent(self,event):
        super().mouseReleaseEvent(event);self.parentWidget().update()


