    def select_tab(self, index):
        self.ribbon.setCurrentIndex(index)
        if hasattr(self, 'tabs'):
            self.tabs.select_tab(index)

    def toggle_maximize(self):
        if self.isMaximized():
            self.showNormal()
        else:
            self.showMaximized()
        self.update_window_corners()

    def changeEvent(self, event):
        if event.type() == QEvent.Type.WindowStateChange:
            self.update_window_corners()
        super().changeEvent(event)

    def get_resize_edge(self, pos):
        if self.isMaximized():
            return None
        margin = 6
        rect = self.rect()
        x, y, w, h = pos.x(), pos.y(), rect.width(), rect.height()
        edge = None
        if x < margin:
            edge = Qt.Edge.LeftEdge
        elif x > w - margin:
            edge = Qt.Edge.RightEdge
        if y < margin:
            edge = Qt.Edge.TopEdge if edge is None else (edge | Qt.Edge.TopEdge)
        elif y > h - margin:
            edge = Qt.Edge.BottomEdge if edge is None else (edge | Qt.Edge.BottomEdge)
        return edge

    def mouseMoveEvent(self, event):
        if not self.isMaximized():
            edge = self.get_resize_edge(event.position().toPoint())
            if edge in (Qt.Edge.LeftEdge, Qt.Edge.RightEdge):
                self.setCursor(Qt.CursorShape.SizeHorCursor)
            elif edge in (Qt.Edge.TopEdge, Qt.Edge.BottomEdge):
                self.setCursor(Qt.CursorShape.SizeVerCursor)
            elif edge in (Qt.Edge.TopEdge | Qt.Edge.LeftEdge, Qt.Edge.BottomEdge | Qt.Edge.RightEdge):
                self.setCursor(Qt.CursorShape.SizeFDiagCursor)
            elif edge in (Qt.Edge.TopEdge | Qt.Edge.RightEdge, Qt.Edge.BottomEdge | Qt.Edge.LeftEdge):
                self.setCursor(Qt.CursorShape.SizeBDiagCursor)
            else:
                self.unsetCursor()
        super().mouseMoveEvent(event)

    def mousePressEvent(self, event):
        if event.button() == Qt.MouseButton.LeftButton and not self.isMaximized():
            edge = self.get_resize_edge(event.position().toPoint())
            if edge is not None:
                handle = self.windowHandle()
                if handle is not None:
                    handle.startSystemResize(edge)
                    event.accept()
                    return
        super().mousePressEvent(event)

    def update_window_corners(self):
        maximized = self.isMaximized()
        radius = "0px" if maximized else "12px"
        dark = getattr(self, 'dark_mode', True)
        border_col = "transparent" if maximized else ("#383838" if dark else "#b6c3d4")
        bg_col = "#1e1e1e" if dark else "#f6f8fa"
        central = self.centralWidget()
        if central:
            central.setStyleSheet(f"""
                #RootContainer {{
                    background-color: {bg_col};
                    border: 1px solid {border_col};
                    border-radius: {radius};
                }}
            """)
        if hasattr(self, 'header_bar'):
            self.header_bar.setStyleSheet(f'#HeaderBar {{background:{"#303030" if dark else "#f6f8fa"};border-top-left-radius:{radius};border-top-right-radius:{radius};}}')
            self.header_bar.update_icons()

    def set_dark_mode(self, enabled):
        self.dark_mode = enabled
        settings = QSettings('ClassicPaint', 'ClassicPaint')
        settings.setValue('dark_mode', enabled)
        if hasattr(self, 'header_bar') and hasattr(self.header_bar, 'theme_act'):
            self.header_bar.theme_act.blockSignals(True)
            self.header_bar.theme_act.setChecked(enabled)
            self.header_bar.theme_act.blockSignals(False)
        if hasattr(self, 'view_dark_mode_checkbox'):
            self.view_dark_mode_checkbox.blockSignals(True)
            self.view_dark_mode_checkbox.setChecked(enabled)
            self.view_dark_mode_checkbox.blockSignals(False)
        self.apply_theme_stylesheet()
        self.update_window_corners()
        if hasattr(self, 'header_bar'):
            self.header_bar.update_icons()
        if hasattr(self, 'scroll'):
            self.scroll.apply_theme(enabled)
        if hasattr(self, 'ribbon_scroll'):
            self.ribbon_scroll.apply_theme(enabled)
            for index in range(self.ribbon.count()):
                self.ribbon.widget(index).update()
        self.update()

