        b.setIconSize(QSize(32,32) if large else QSize(16,16))
        b.setToolButtonStyle(Qt.ToolButtonStyle.ToolButtonTextUnderIcon if large else Qt.ToolButtonStyle.ToolButtonTextBesideIcon)
        b.setFixedSize(56,69) if large else b.setFixedHeight(23)
        body.addWidget(b);return b


